import sys, json
sys.path.insert(0, __import__("os").path.dirname(__file__))
from harness import *

start()
try:
    a, b, c = user("ana", "ana@x.com"), user("beto"), user("cris")

    print("Cuentas, ligas y planes (etapa 1-2)")
    check("crear liga", val("ana", "select create_league('Liga Reforma')") == "liga-reforma")
    check("rol inventado se rechaza", fails("ana", "select set_roles(array['admin'])", "check"))
    check("nadie se da Pro", fails("beto", "insert into subscriptions (subject_type,subject_id,plan_id) values ('team','x/y','team-pro')"))
    check("equipo nuevo", "los-halcones" in val("beto", "select create_team('Los Halcones', 7)"))
    check("tope de equipos del plan gratis", fails("beto", "select create_team('Otro', 7)", "máximo"))
    check("solo el admin agrega jugadores", fails("cris", "select add_player('los-halcones','principal','Intruso','1','')", "sin permiso"))

    print("Invitaciones, vinculación y Pro por contrato (etapa 3)")
    check("la liga crea invitación", re.fullmatch(r"[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{4}", code := val("ana", "select create_invite('liga-reforma','Temporada otoño', 5, 30)")) is not None, code)
    check("quien no administra la liga no crea invitaciones", fails("beto", "select create_invite('liga-reforma','x')", "sin permiso"))
    check("beto no ve las invitaciones de ana", val("beto", "select count(*) from league_invites") == "0")
    check("código malo no da pista", json.loads(val("beto", "select request_link('AAAA-BBBB-CCCC','los-halcones','principal')"))["error"] == "invalid")
    check("solo el delegado del equipo vincula", fails("cris", f"select request_link('{code}','los-halcones','principal')", "sin permiso"))
    r = json.loads(val("beto", f"select request_link(lower('{code}'),'los-halcones','principal')"))
    check("solicitud con código válido (acepta minúsculas)", r.get("ok") is True, r)
    check("no se duplica la solicitud", json.loads(val("beto", f"select request_link('{code}','los-halcones','principal')")).get("error") == "duplicate")
    check("sin contrato, el equipo sigue gratis", json.loads(val("beto", "select entitlement('team','los-halcones/principal')"))["name"] == "Equipo Gratis")
    lt = val("ana", "select id from league_teams limit 1")
    check("beto no puede aprobar su propia solicitud", fails("beto", f"select decide_link('liga-reforma','{lt}',true)", "sin permiso"))
    r = json.loads(val("ana", f"select decide_link('liga-reforma','{lt}',true)"))
    check("aprobado sin contrato: vinculado pero sin Pro", r == {"ok": True, "pro": False}, r)
    q("srv", "insert into league_contracts (league_id, pro_slots) values ('liga-reforma', 1)")
    check("sin cupo asignado no hay Pro aunque haya contrato", json.loads(val("beto", "select entitlement('team','los-halcones/principal')"))["name"] == "Equipo Gratis")
    check("la liga asigna Pro dentro del cupo", val("ana", f"select set_team_pro('liga-reforma','{lt}',true)") == "")
    e = json.loads(val("beto", "select entitlement('team','los-halcones/principal')"))
    check("el equipo recibe Pro de la liga", e["name"] == "Equipo Pro" and e["source"] == "league" and e["league_id"] == "liga-reforma", e)
    check("beto no ve contratos ajenos", val("beto", "select count(*) from league_contracts") == "0")
    check("contrato visible para la liga", json.loads(val("ana", "select league_contract('liga-reforma')"))["used"] == 1)
    # segundo equipo: no cabe en el cupo
    user("dana"); q("dana", "select create_team('Tigres', 7)")
    code2 = val("ana", "select create_invite('liga-reforma','otro')")
    check("segundo equipo solicita", json.loads(val("dana", f"select request_link('{code2}','tigres','principal')")).get("ok"))
    lt2 = val("ana", "select id from league_teams where club_id='tigres'")
    check("se aprueba sin Pro cuando el cupo está lleno", json.loads(val("ana", f"select decide_link('liga-reforma','{lt2}',true)")) == {"ok": True, "pro": False})
    check("no se excede el cupo manualmente", fails("ana", f"select set_team_pro('liga-reforma','{lt2}',true)", "espacios"))
    # vencimiento
    q("srv", "update league_contracts set ends_at = now() - interval '1 day'")
    check("contrato vencido retira solo el Pro de liga", json.loads(val("beto", "select entitlement('team','los-halcones/principal')"))["name"] == "Equipo Gratis")
    check("contrato vencido: equipo y jugadores intactos", val("srv", "select count(*) from team_docs where club_id='los-halcones'") == "1")
    q("srv", "update league_contracts set ends_at = null")
    # Pro propio se conserva
    q("srv", "insert into subscriptions (subject_type,subject_id,plan_id,source) values ('team','los-halcones/principal','team-pro','manual')")
    q("srv", "update league_contracts set status='canceled'")
    e = json.loads(val("beto", "select entitlement('team','los-halcones/principal')"))
    check("liga cancelada: conserva su Pro propio", e["name"] == "Equipo Pro" and e["source"] == "manual", e)
    q("srv", "update league_contracts set status='active'")
    e = json.loads(val("beto", "select entitlement('team','los-halcones/principal')"))
    check("con ambos, gana la suscripción propia", e["source"] == "manual", e)
    # desvincular
    check("un tercero no desvincula", fails("cris", f"select unlink_team('{lt}')", "sin permiso"))
    check("el delegado se desvincula", val("beto", f"select unlink_team('{lt}')") == "")
    check("historial conservado (status left)", val("srv", f"select status from league_teams where id='{lt}'") == "left")
    q("srv", "delete from subscriptions")
    check("desvinculado: ya no hay Pro de liga", json.loads(val("beto", "select entitlement('team','los-halcones/principal')"))["name"] == "Equipo Gratis")
    check("puede volver a solicitar", json.loads(val("beto", f"select request_link('{code}','los-halcones','principal')")).get("ok"))
    # invitación: usos, revocación, intentos
    check("revocar invitación", val("ana", f"select revoke_invite('liga-reforma','{code2}')") == "")
    check("invitación revocada no sirve", json.loads(val("dana", f"select request_link('{code2}','tigres','principal')")).get("error") in ("invalid", "duplicate"))
    for i in range(8): q("beto", "select request_link('ZZZZ-ZZZZ-ZZZZ','los-halcones','principal')")
    check("bloqueo tras muchos intentos fallidos", json.loads(val("beto", f"select request_link('{code}','los-halcones','principal')")).get("error") == "throttled")
    check("bitácora registra acciones", int(val("ana", "select count(*) from audit_log where league_id='liga-reforma'")) >= 5)
    check("beto no lee la bitácora", val("beto", "select count(*) from audit_log") == "0")
    check("nadie edita la bitácora", fails("ana", "delete from audit_log"))
    check("funciones internas no son llamables", fails("ana", "select league_pro_teams()") and fails("ana", "select log_action('liga-reforma','x')"))
    check("beto ve los vínculos de su equipo", int(val("beto", "select count(*) from team_links('los-halcones','principal')")) >= 2)
    check("cris no ve vínculos ajenos", val("cris", "select count(*) from team_links('los-halcones','principal')") == "0")
    print("Gestión de equipos (etapa 4)")
    ok_, _ = q("beto", "select 1")
    check("formato 5 ahora es válido", "ana-f5" in val("cris", "select create_team('Ana F5', 5)"))
    check("formato inventado se rechaza", fails("cris", "select create_team('Raro', 10)", "formato"))
    q("srv", "update plans set limits = jsonb_set(limits, '{teams}', '5') where id='team-free'")   # solo para probar sin tope de equipos
    # equipo con plan gratis (beto: los-halcones)
    pid = val("beto", "select add_player('los-halcones','principal','Carlos Ruiz','9','DC')")
    check("agregar jugador", pid.startswith("p"), pid)
    check("editar jugador", val("beto", f"select update_player('los-halcones','principal','{pid}','Carlos R. Ruiz','10','MCO')") == "")
    check("el cambio se refleja en roster y jugadores", val("srv", f"select (select e->>'number' from team_docs d, jsonb_array_elements(d.data->'roster') e where d.club_id='los-halcones' and e->>'player'='{pid}')||'/'||(select e->>'name' from club_docs, jsonb_array_elements(players) e where id='los-halcones' and e->>'id'='{pid}')") == "10/Carlos R. Ruiz")
    check("otro usuario no edita jugadores ajenos", fails("cris", f"select update_player('los-halcones','principal','{pid}','X','1','')", "sin permiso"))
    check("dar de baja conserva al jugador", val("beto", f"select set_player_status('los-halcones','principal','{pid}','congelado')") == "" and val("srv", "select jsonb_array_length(players) from club_docs where id='los-halcones'") != "0")
    q("srv", "update plans set limits = jsonb_set(limits, '{players}', '1') where id='team-free'")   # límite temporal para probar
    p2 = val("beto", "select add_player('los-halcones','principal','Segundo','2','')")
    check("el jugador dado de baja no ocupa lugar del límite", p2.startswith("p"), p2)
    check("se respeta el límite de jugadores activos", fails("beto", "select add_player('los-halcones','principal','Tercero','3','')", "límite"))
    q("beto", f"select set_player_status('los-halcones','principal','{p2}','congelado')")
    check("dar de baja libera un lugar", val("beto", "select add_player('los-halcones','principal','Tercero','3','')").startswith("p"))
    q("srv", "update plans set limits = jsonb_set(limits, '{players}', '30') where id='team-free'")
    check("reactivar jugador", val("beto", f"select set_player_status('los-halcones','principal','{pid}','activo')") == "" and val("srv", f"select count(*) from team_docs d, jsonb_array_elements(d.data->'roster') e where d.club_id='los-halcones' and e->>'player'='{pid}' and e ? 'status'") == "0")
    check("estado inventado se rechaza", fails("beto", f"select set_player_status('los-halcones','principal','{pid}','borrado')", "no válidos"))
    check("jugador inexistente", fails("beto", "select update_player('los-halcones','principal','p999','Nadie','1','')", "no encontrado"))

    mid = val("beto", """select save_match('los-halcones','principal','{"jornada":"J1","date":"2026-11-01T09:10:00-07:00","rival":"Cañoneros","home":true,"venue":"Cancha 2"}')""")
    check("agregar partido", mid.startswith("m"), mid)
    check("editar partido", val("beto", f"""select save_match('los-halcones','principal','{{"id":"{mid}","jornada":"J1","date":"2026-11-02T10:00:00-07:00","rival":"Cañoneros FC","home":false,"venue":"Cancha 3"}}')""") == mid and val("srv", f"select e->>'rival' from team_docs d, jsonb_array_elements(d.data->'matches') e where d.club_id='los-halcones'") == "Cañoneros FC")
    check("fecha inválida se rechaza", fails("beto", """select save_match('los-halcones','principal','{"date":"nunca","rival":"X"}')""", "fecha"))
    check("sin rival se rechaza", fails("beto", """select save_match('los-halcones','principal','{"date":"2026-11-01T09:00:00-07:00","rival":""}')""", "rival"))
    check("otro usuario no agenda partidos", fails("cris", """select save_match('los-halcones','principal','{"date":"2026-11-01T09:00:00-07:00","rival":"X"}')""", "sin permiso"))
    q("srv", f"insert into results (club_id,team_id,match_id,score_for,score_against,played) values ('los-halcones','principal','{mid}',2,1,'{{}}')")
    check("un partido con resultado no se borra", fails("beto", f"select delete_match('los-halcones','principal','{mid}')", "resultado"))
    mid2 = val("beto", """select save_match('los-halcones','principal','{"date":"2026-12-01T09:00:00-07:00","rival":"Borrable"}')""")
    check("un partido sin resultado sí se borra", val("beto", f"select delete_match('los-halcones','principal','{mid2}')") == "" and val("srv", "select jsonb_array_length(data->'matches') from team_docs where club_id='los-halcones'") == "1")

    print("Datos, colores y escudo del equipo")
    check("editar nombre, torneo y formato", val("beto", "select update_team('los-halcones','principal','Halcones del Norte','Liga Reforma Intermedia',9)") == "" and val("srv", "select (club->>'name')||'/'||(select data->>'format' from team_docs where club_id='los-halcones') from club_docs where id='los-halcones'") == "Halcones del Norte/9")
    check("formato inválido al editar", fails("beto", "select update_team('los-halcones','principal','X Y','',10)", "formato"))
    check("otro usuario no edita el equipo", fails("cris", "select update_team('los-halcones','principal','Hack','',7)", "sin permiso"))
    check("colores solo con la función Pro", fails("beto", """select set_theme('los-halcones','principal','{"primary":"#112233"}','escudo','franjas')""", "plan"))
    q("srv", "insert into subscriptions (subject_type,subject_id,plan_id,source) values ('team','los-halcones/principal','team-pro','manual')")
    check("con Pro cambia colores", val("beto", """select set_theme('los-halcones','principal','{"primary":"#112233"}','redonda','diagonal')""") == "" and val("srv", "select club->'theme'->'colors'->>'primary' from club_docs where id='los-halcones'") == "#112233")
    check("el tema conserva los demás colores", val("srv", "select club->'theme'->'colors'->>'bg' from club_docs where id='los-halcones'") == "#0e1110")
    check("color inválido se rechaza", fails("beto", """select set_theme('los-halcones','principal','{"primary":"rojo"}','escudo','franjas')""", "no válidos"))
    check("clave de color inventada se rechaza", fails("beto", """select set_theme('los-halcones','principal','{"evil":"#112233"}','escudo','franjas')""", "no válidos"))
    bu = UID["beto"]
    check("escudo: enlace propio válido", val("beto", f"select set_crest('los-halcones','https://x.supabase.co/storage/v1/object/public/photos/{bu}/crest.png')") == "")
    check("escudo: enlace ajeno se rechaza", fails("beto", "select set_crest('los-halcones','https://evil.com/x.png')", "no válidos"))
    check("escudo: carpeta de otro usuario se rechaza", fails("beto", f"select set_crest('los-halcones','https://x.supabase.co/storage/v1/object/public/photos/{UID['cris']}/crest.png')", "no válidos"))
    q("srv", "delete from subscriptions")

    print("Finanzas del equipo y funciones por plan")
    fin = '{"cuota":350,"cuotaNota":"Cubre inscripción","liga":[{"label":"Inscripción","costo":2500,"desc":"Entrada"}],"gastos":[{"label":"Árbitro","costo":300}],"multaTotal":0,"multas":[]}'
    check("finanzas requieren la función del plan", fails("beto", f"select save_finance('los-halcones','principal','{fin}')", "finanzas"))
    check("un pago no entra sin la función del plan", fails("beto", f"insert into payments (club_id,team_id,user_id,player_id,kind,amount,status) values ('los-halcones','principal','{bu}','{pid}','cuota',100,'approved')"))
    q("srv", "insert into subscriptions (subject_type,subject_id,plan_id,source) values ('team','los-halcones/principal','team-pro','manual')")
    check("con Pro se guardan las finanzas", val("beto", f"select save_finance('los-halcones','principal','{fin}')") == "")
    f = json.loads(val("srv", "select data->'finance' from team_docs where club_id='los-halcones'"))
    check("conceptos con clave y pagado en cero", f["liga"][0]["k"] == "inscripcion" and f["liga"][0]["pagado"] == 0 and f["gastos"][0]["k"] == "arbitro", f)
    check("orden y cuentas generados (sin jugadores dados de baja)", f["orden"] == ["inscripcion", "arbitro"] and sorted(x["player"] for x in f["cuentas"]) == ["p1", "p3"], f)   # p2 está dado de baja
    val("beto", """select save_finance('los-halcones','principal','{"cuota":350,"liga":[{"label":"Inscripción","costo":100,"pagado":999}]}')""")
    check("el cliente no puede mandar lo pagado", json.loads(val("srv", "select data->'finance'->'liga'->0 from team_docs where club_id='los-halcones'"))["pagado"] == 0)
    check("cuota inválida se rechaza", fails("beto", """select save_finance('los-halcones','principal','{"cuota":-5}')""", "no válidos"))
    check("otro usuario no guarda finanzas", fails("cris", f"select save_finance('los-halcones','principal','{fin}')", "sin permiso"))
    check("multa repartida entre marcados", val("beto", f"""select save_finance('los-halcones','principal','{{"cuota":350,"multaTotal":200,"multas":[{{"player":"{pid}","why":"Tarjetas"}}]}}')""") == "" and json.loads(val("srv", "select data->'finance'->'cuentas'->0 from team_docs where club_id='los-halcones'"))["multa"] is True)
    check("el administrador registra ingreso", val("beto", f"insert into payments (club_id,team_id,user_id,kind,amount,detail,status,decided_at) values ('los-halcones','principal','{bu}','ingreso',500,'Patrocinio','approved',now()) returning kind") .startswith("ingreso"))
    q("cris", "select join_team('los-halcones','principal','','Cris Jugador')")
    q("beto", f"update members set status='approved', player_id='{pid}' where user_id='{UID['cris']}'")
    cu = UID["cris"]
    check("un jugador no registra ingresos", fails("cris", f"insert into payments (club_id,team_id,user_id,kind,amount,status,decided_at) values ('los-halcones','principal','{cu}','ingreso',500,'approved',now())"))
    check("un jugador no se aprueba su propio pago", fails("cris", f"insert into payments (club_id,team_id,user_id,player_id,kind,amount,status,decided_at) values ('los-halcones','principal','{cu}','{pid}','cuota',100,'approved',now())"))
    check("un jugador sí reporta su pago (queda pendiente)", val("cris", f"insert into payments (club_id,team_id,user_id,player_id,kind,amount) values ('los-halcones','principal','{cu}','{pid}','cuota',100) returning status") .startswith("pending"))
    q("srv", "delete from subscriptions")
    check("sin Pro tampoco se votan calificaciones", fails("beto", f"insert into attr_votes (club_id,team_id,voter,target,vel,tir,pas,reg,def,fis) values ('los-halcones','principal','{bu}','p9',5,5,5,5,5,5)"))
    check("equipos de archivo no se restringen", val("srv", "select has_feature('diablos','domingos','finance')") == "t")
finally:
    ok = summary(); stop(); sys.exit(0 if ok else 1)
